// ME: LENS cabin cutaway: static vehicle meshes (body shell, windows).
// Same inputs as the game's vehicle_multiuv_static shader, plus the untransformed
// mesh position so the fragment shader can clip against the cut plane.

varying vec3 vertColour;
varying vec3 vertNormal;
varying vec2 texCoords;
varying vec2 texCoords1;
varying vec4 positionEye;
varying vec3 meLensMeshPos;
varying vec3 meLensMeshNormal;

texCoords1 = uv2.st;
meLensMeshPos = vertex.xyz;
meLensMeshNormal = normal.xyz;
